using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

const string modelId = "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var notebook = new ResearchNotebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (string query) => WebSearchTool.SearchAsync(query),
        nameof(WebSearchTool.SearchAsync),
        "Search the web for information on a topic. Returns a list of results with titles, URLs, and snippets."),

    AIFunctionFactory.Create(
        ([Description("The title or heading for this note")] string title,
         [Description("The note content to save")] string content) =>
        {
            notebook.AddNote(title, content);
            return $"Note saved: \"{title}\"";
        },
        "SaveNote",
        "Save a research note with a title and content. Use this to record important findings."),

    AIFunctionFactory.Create(
        () => notebook.GetAllNotes(),
        "GetNotes",
        "Retrieve all saved research notes so far."),
};

const string instructions = """
    You are a research agent. Given a topic, you must:
    1. Search the web for relevant information using multiple queries.
    2. Save key findings as notes using the SaveNote tool.
    3. After gathering enough information (at least 3 searches), retrieve your
       notes and produce a well-structured summary with sources.
    Be thorough but concise. Cite URLs where possible.
    """;

var agent = chatClient.AsAIAgent(
    instructions: instructions,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent               ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.Write("Enter a research topic (or 'quit' to exit): ");

while (Console.ReadLine() is { } topic && !topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(topic))
    {
        Console.Write("\nEnter a research topic (or 'quit' to exit): ");
        continue;
    }

    Console.WriteLine($"\nResearching: {topic}\n");
    notebook.Clear();

    try
    {
        var session = await agent.CreateSessionAsync();
        var response = await agent.RunAsync(
            topic,
            session,
            new ChatClientAgentRunOptions(new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 4096,
            }));

        Console.WriteLine("═══ Research Summary ═══\n");
        Console.WriteLine(response.Text);
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}");
    }

    Console.Write("Enter a research topic (or 'quit' to exit): ");
}

Console.WriteLine("Goodbye!");

// --- Tool implementations ---

internal static class WebSearchTool
{
    private static readonly HttpClient s_httpClient = new();

    public static async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var json = await s_httpClient.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            // Abstract (instant answer)
            var abstractText = json.TryGetProperty("AbstractText", out var at) ? at.GetString() : null;
            var abstractUrl = json.TryGetProperty("AbstractURL", out var au) ? au.GetString() : null;
            if (!string.IsNullOrEmpty(abstractText))
            {
                results.Add($"**Summary**: {abstractText}\nSource: {abstractUrl}");
            }

            // Related topics
            if (json.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = item.TryGetProperty("FirstURL", out var fu) ? fu.GetString() : null;
                    if (!string.IsNullOrEmpty(text))
                    {
                        results.Add($"- {text}\n  URL: {firstUrl}");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for \"{query}\". Try a different search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
        }
    }
}

internal sealed class ResearchNotebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public void AddNote(string title, string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"[Note {i + 1}] {n.Title}\n{n.Content}"));
    }

    public void Clear() => _notes.Clear();
}

